hooks.command:
node -e 'try {
  const fs = require("node:fs");
  const { spawn } = require("node:child_process");
  const input = JSON.parse(fs.readFileSync(0, "utf8"));
  if (!input.transcript_path) process.exit(0);
  const text = fs.readFileSync(input.transcript_path, "utf8").trim().split("\n")
    .map(line => JSON.parse(line)).filter(entry => entry.type === "assistant")
    .map(entry => Array.isArray(entry.message.content)
      ? entry.message.content.filter(block => block.type === "text").map(block => block.text).join(" ")
      : entry.message.content).join("\n");
  const summary = Buffer.from(text).subarray(-2000).toString("utf8").replace(/\n/g, " ").slice(0, 1500);
  if (summary.length < 20) process.exit(0);
  const env = { ...process.env,
    ENGRAM_DB_PATH: process.env.ENGRAM_DB_PATH || "~/.engram/engram.db",
    ENGRAM_SOURCE: process.env.ENGRAM_SOURCE || "claude-code"
  };
  const child = spawn("npx", ["-y", "-p", "@engram-ai-memory/mcp@latest", "engram-store-session", "Session summary: " + summary], {
    detached: true, stdio: "ignore",
    env
  });
  child.on("error", () => {});
  child.unref();
} catch {}' >/dev/null 2>&1 || true
